class DatElaborarPagosReferencia extends BaseDatElaborarPagoReferencia
{

    public static function obtenerObjDatElaborarPagosReferenciaDadoId($id)
    {
        return Doctrine::getTable('DatElaborarPagosReferencia')->find($id);
    }

    public static function obtenerIdElaborarPagosReferenciadosdadoIdElaborarPagos($idelaborarpagos)
    {
        $result = Doctrine_Query::create()
            ->select('*')
            ->from('DatElaborarPagosReferencia')
            ->where('idelaborarpagos = ?', array($idelaborarpagos))
            ->fetchArray();
        return $result;
    }
}
